INSERT INTO notice_config (notice_no, notice_type, title, content, source_type, priority, publish_time, status) VALUES
('QA_1102_MAINT', 'MAINTENANCE', '停服维护预告 · 11月5日 06:00-08:00',
 '各位冒险者:\n为提升服务器稳定性,我们将于 11 月 5 日 06:00-08:00 进行停服维护,维护期间无法登录游戏。\n维护完成后,所有玩家将收到体力 ×60 的补偿邮件,请注意查收。\n给您带来的不便,敬请谅解。', 'QA', 50, '2026-11-02 09:00:00', 1),
('QA_1102_VER', 'VERSION', '新玩法「矿境掠夺」开放说明',
 '各位冒险者:\n矿境掠夺玩法已于 11 月 1 日开放,玩家等级达到 Lv.10 即可从终端进入。\n1. NPC 矿:按顺序挑战 60 座矿点,首次通关可获得额外奖励。\n2. 真人矿:匹配实力相近的玩家矿点进行掠夺,胜利可夺取对方矿库中的部分矿晶。\n3. 保护盾:购买保护盾后 24 小时内不会被其他玩家掠夺;新手保护期内同样不会被掠夺。\n4. 复仇:被掠夺后可在战报中对掠夺者发起一次复仇,胜利可夺回部分矿晶。\n5. 战报:最近的掠夺与被掠夺记录都会保留在战报中,方便随时查看。\n矿境中还藏有更高难度的精英矿点,挑战成功可获得稀有矿石与专属奖励。\n祝各位冒险者满载而归!', 'QA', 40, '2026-11-01 10:00:00', 1),
('QA_1102_ACT', 'ACTIVITY', '(不应出现)限时活动', '活动类公告走单独入口,不在公告弹框里显示。', 'QA', 60, '2026-11-02 08:00:00', 1),
('QA_1102_GIFT', 'HOME', '兑换码使用说明', '在终端点击「兑换码」,输入礼包码即可领取奖励。每个礼包码每个账号只能使用一次。', 'QA', 30, '2026-10-30 12:00:00', 1),
('QA_1102_FB', 'HOME', '玩家反馈渠道说明', '遇到问题可发送邮件至 support@lootchain.game,我们会尽快回复。', 'QA', 20, '2026-10-28 12:00:00', 1);
